import{_ as s,a0 as r,w as i,s as l,ao as p,I as u,x as e,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"環境音播放器：讓人放鬆的聲音，保持你的創造力 | LCTT x X-CMD","titleTemplate":false,"description":"環境音播放器：讓人放鬆的聲音，保持你的創造力 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"環境音播放器：讓人放鬆的聲音，保持你的創造力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"環境音播放器：讓人放鬆的聲音，保持你的創造力 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150407 Ambient Noise Player for Ubuntu Plays Relaxing Sounds to Keep You Creative","title":"環境音播放器：讓人放鬆的聲音，保持你的創造力","tag":"201505","desc":""},"relativePath":"201505/20150407 Ambient Noise Player for Ubuntu Plays Relaxing Sounds to Keep You Creative.md","filePath":"[post].md"}'),d={name:"201505/20150407 Ambient Noise Player for Ubuntu Plays Relaxing Sounds to Keep You Creative.md"};function m(b,t,f,g,T,x){const o=r("Link");return i(),l("div",null,[t[16]||(t[16]=p('<h1 id="環境音播放器-讓人放鬆的聲音-保持你的創造力" tabindex="-1">環境音播放器：讓人放鬆的聲音，保持你的創造力 <a class="header-anchor" href="#環境音播放器-讓人放鬆的聲音-保持你的創造力" aria-label="Permalink to “環境音播放器：讓人放鬆的聲音，保持你的創造力”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/04/raining-1600x900-wallpaper_www.wallpapermay.com_84-1.jpg" alt="Rain is a soothing sound for some"></p><p><em>對於某些人來説雨聲是個令人安心的聲音</em></p><p><strong>如果我想變得非常有效率，我不能聽‘正常’的音樂。它會使我分心，我會開始跟着唱或者讓我想起另一首歌，結局就是我在自己的音樂庫裏到處戳並且……反正，你懂的。</strong></p><p>同樣我也不能在寂靜的環境中工作（雖然和6只貓生活在一起意味着這不太可能）但是無規律的刺耳聲音和突然地咔噠聲以及貓叫聲會打破寂靜。</p><p>我的解決辦法是聽<strong>環境音</strong>。</p><p>我發現它能幫助我消除大腦的裏的胡思亂想，提供了一個聲景覆蓋了貓咪玩耍的聲音。</p><p>環境音就是日常生活中的背景噪音；雨滴在窗户上敲打的聲音，咖啡店裏人們聊天的嗡嗡聲，風中鳥兒們閒聊的聲音，等等。</p><p>傾聽這些聲音會強迫一個瘋狂運行的大腦減速，重新沉靜下來重新把精力聚集到重要的事情上。</p><h3 id="適用於ubuntu的環境音應用" tabindex="-1">適用於Ubuntu的環境音應用 <a class="header-anchor" href="#適用於ubuntu的環境音應用" aria-label="Permalink to “適用於Ubuntu的環境音應用”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/04/ambient-noise-player-750x365.jpg" alt=""></p><p>Google Play和蘋果應用商店充滿了環境音和白噪聲的應用。現在，在Ubuntu裏有同樣的應用了。</p>',12)),u("p",null,[t[1]||(t[1]=e("‘",-1)),n(o,{href:"http://anoise.tuxfamily.org/"},{default:a(()=>[...t[0]||(t[0]=[e("Ambient Noise （環境音）",-1)])]),_:1}),t[2]||(t[2]=e(" ’——人如其名，這是一個專門被設計成播放這種聲音的音頻播放器。他甚至可以同Ubuntu聲音菜單整合到一起，給你‘選擇，點擊即放鬆’的體驗。",-1))]),t[17]||(t[17]=p(`<p>這個應用（又被稱為‘ANoise播放器’，由Marcos Costales製作）帶有<strong>8個高品質音頻</strong>。</p><p>這8個預設音頻涵蓋了多種環境，從下雨時有節奏的聲音，到夜晚大自然靜謐的旋律，還有下午熙熙攘攘的咖啡店的嗡嗡聲。</p><h3 id="在ubuntu上安裝anoise播放器" tabindex="-1">在Ubuntu上安裝ANoise播放器 <a class="header-anchor" href="#在ubuntu上安裝anoise播放器" aria-label="Permalink to “在Ubuntu上安裝ANoise播放器”">​</a></h3><p>適用於Ubuntu的環境音播放器是個免費的應用而且可以從它專用的PPA裏安裝。</p><p>要這樣安裝請先打開一個新的終端窗口運行:</p><pre><code>sudo add-apt-repository ppa:costales/anoise

sudo apt-get update &amp;&amp; sudo apt-get install anoise
</code></pre><p>安裝好以後只需從Unity Dash（或桌面環境裏類同的地方）裏打開它，通過聲音菜單選擇你喜歡的環境音然後……放鬆吧！這個應用甚至記得你上次用的環境音。</p><p>即便如此，你還是要試一試看它是否能滿足你的需要。我要説的是讓我知道你是怎麼想的，但是我將會專心致志到聽不到你的聲音——你可能也會這樣！</p><hr>`,9)),u("p",null,[t[4]||(t[4]=e("via: ",-1)),n(o,{href:"http://www.omgubuntu.co.uk/2015/04/ambient-noise-player-app-for-ubuntu-linux"},{default:a(()=>[...t[3]||(t[3]=[e("http://www.omgubuntu.co.uk/2015/04/ambient-noise-player-app-for-ubuntu-linux",-1)])]),_:1})]),u("p",null,[t[8]||(t[8]=e("作者：",-1)),n(o,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[5]||(t[5]=[e("Joey-Elijah Sneddon",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),n(o,{href:"https://github.com/H-mudcup"},{default:a(()=>[...t[6]||(t[6]=[e("H-mudcup",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),u("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const P=s(d,[["render",m]]);export{_ as __pageData,P as default};
